import * as fs from 'node:fs/promises';
import {mock} from 'node:test';
import {spawnSync} from 'node:child_process';
import {AsyncLocalStorage} from 'node:async_hooks';
const base='/tmp/codex-tool-runs/svton/m2-r2-nonce-review-20260930';
const dir=await fs.mkdtemp(base+'/race-'),file=dir+'/state.json',lock=file+'.lock',prev=lock+'.prev';
const child=spawnSync(process.execPath,['-e','process.exit(0)']);
try{process.kill(child.pid,0);throw Error('fixture PID reused')}catch(e){if(e.code!=='ESRCH')throw e;}
await fs.writeFile(lock,`${child.pid}\tdead-owner-token\n`);
const defer=()=>{let resolve;const promise=new Promise(r=>resolve=r);return {promise,resolve}};
const before=defer(),resume=defer(),aRename=defer(),resumeARename=defer(),bRename=defer(),resumeBRename=defer(),aEntered=defer(),bEntered=defer(),releaseA=defer(),releaseB=defer();
const als=new AsyncLocalStorage();let paused=false,active=0,maxActive=0,bActive=false,overwroteLiveB=false,oldDirInode;
const {default:ignored,...named}=fs;
mock.module('node:fs/promises',{namedExports:{...named,
 open:async(p,flags,...args)=>{
  if(als.getStore()==='A'&&p.startsWith(prev+'/owner.')&&!paused){paused=true;oldDirInode=(await fs.stat(prev)).ino;before.resolve();await resume.promise;}
  return fs.open(p,flags,...args);
 },
 rename:async(from,to)=>{
  if(to===lock&&als.getStore()==='A'){aRename.resolve();await resumeARename.promise;overwroteLiveB=bActive;}
  if(to===lock&&als.getStore()==='B'){bRename.resolve();await resumeBRename.promise;}
  return fs.rename(from,to);
 }
}});
const {withFileLock}=await import('/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js');
const guard=setTimeout(()=>{console.error('REPRO_TIMEOUT');process.exit(2)},10000);
const a=als.run('A',()=>withFileLock(file,async()=>{active++;maxActive=Math.max(maxActive,active);aEntered.resolve();await releaseA.promise;active--;},{timeoutMs:5000}));
await before.promise;await new Promise(r=>setTimeout(r,650));
const b=als.run('B',()=>withFileLock(file,async()=>{bActive=true;active++;maxActive=Math.max(maxActive,active);bEntered.resolve();await releaseB.promise;active--;bActive=false;},{timeoutMs:5000}));
await bRename.promise;resume.resolve();await aRename.promise;
const recordsBeforeReplace=await fs.readdir(prev);const currentDirInode=(await fs.stat(prev)).ino;
resumeBRename.resolve();await bEntered.promise;const bLock=await fs.readFile(lock,'utf8');
resumeARename.resolve();await aEntered.promise;
const result={maxActive,activeAtObservation:active,overwroteLiveB,bLockChanged:await fs.readFile(lock,'utf8')!==bLock,recordsBeforeReplace,oldDirInode,currentDirInode,onlySchedulingMocked:true};
releaseA.resolve();await a;releaseB.resolve();await b;clearTimeout(guard);mock.restoreAll();
await fs.writeFile(base+'/nonce-race-result.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));
